import{_ as e,c as t,o as i,ae as r}from"./chunks/framework.Cd-3tpCq.js";const f=JSON.parse('{"title":"介绍","description":"MinecraftSounds 我的世界音乐包生成器介绍","frontmatter":{"title":"介绍","description":"MinecraftSounds 我的世界音乐包生成器介绍"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),n={name:"guide/index.md"};function o(l,a,s,d,c,h){return i(),t("div",null,a[0]||(a[0]=[r('<h1 id="minecraftsounds-音乐包生成器-介绍" tabindex="-1">MinecraftSounds 音乐包生成器 介绍 <a class="header-anchor" href="#minecraftsounds-音乐包生成器-介绍" aria-label="Permalink to &quot;MinecraftSounds 音乐包生成器 介绍&quot;">​</a></h1><p>因为发现有很多小白，想在我的世界里播放自己想听的音乐或者音效，所以制作了这个生成器。</p><p>软件使用Python，界面使用pyqt5。使用AI辅助开发。<br> UI界面设计了一个类似 我的世界 风格的界面，操作起来非常方便。</p><h2 id="什么是音乐包" tabindex="-1">什么是音乐包？ <a class="header-anchor" href="#什么是音乐包" aria-label="Permalink to &quot;什么是音乐包？&quot;">​</a></h2><p>在我的世界中，音乐包（Resource Pack 的一部分）允许玩家自定义游戏中的各种音效，包括：</p><ul><li>背景音乐</li><li>环境音效</li><li>生物音效</li><li>方块音效</li><li>界面音效</li><li>等等</li></ul><p>通过替换或添加这些音效，玩家可以获得全新的游戏体验。</p><h2 id="为什么选择-minecraftsounds-音乐包生成器" tabindex="-1">为什么选择 MinecraftSounds 音乐包生成器？ <a class="header-anchor" href="#为什么选择-minecraftsounds-音乐包生成器" aria-label="Permalink to &quot;为什么选择 MinecraftSounds 音乐包生成器？&quot;">​</a></h2><h3 id="简单易用" tabindex="-1">简单易用 <a class="header-anchor" href="#简单易用" aria-label="Permalink to &quot;简单易用&quot;">​</a></h3><p>我们的设计理念是「让每个人都能创建自己的音乐包」。即使你没有任何基础知识，也能通过我们直观的界面轻松创建音乐包。</p><h3 id="功能全面" tabindex="-1">功能全面 <a class="header-anchor" href="#功能全面" aria-label="Permalink to &quot;功能全面&quot;">​</a></h3><ul><li><strong>可视化编辑</strong>：拖拽式界面，所见即所得</li><li><strong>音效预览</strong>：实时预览音效效果</li><li><strong>批量处理</strong>：支持批量导入和编辑音效</li><li><strong>版本兼容</strong>：支持最新版本的我的世界，同时兼容旧版本</li><li><strong>项目管理</strong>：轻松管理多个音乐包项目</li></ul><h3 id="开源免费" tabindex="-1">开源免费 <a class="header-anchor" href="#开源免费" aria-label="Permalink to &quot;开源免费&quot;">​</a></h3><p>MinecraftSounds 是一个开源项目，完全免费使用。我们相信，通过社区的力量，可以让这个工具变得更加强大和易用。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>准备好开始创建你的第一个音乐包了吗？请查看我们的<a href="/guide/getting-started.html">快速开始</a>指南，了解如何安装和使用 MinecraftSounds 音乐包生成器。</p><p>如果你已经有了一些经验，可以直接前往<a href="/tutorials/">教程</a>部分，学习更多高级功能的使用方法。</p>',17)]))}const p=e(n,[["render",o]]);export{f as __pageData,p as default};
